  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Combattant-&#192;-Deux-Mains-(Guerrier).html&quot; title=&quot;Combattant &#224; deux mains&quot;&gt;Combattant &#224; deux mains&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Combattant-De-La-Main-Libre-(Guerrier).html&quot; title=&quot;Combattant de la main libre&quot;&gt;Combattant de la main libre&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Combattant-D&#233;loyal-(Guerrier).html&quot; title=&quot;Combattant d&#233;loyal&quot;&gt;Combattant d&#233;loyal&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Orque-(Race).html&quot; title=&quot;Les orques&quot;&gt;Orque&lt;/a&gt;) (MR)&lt;/li&gt;
