  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;fenseur-Molthuni-(Guerrier).html&quot; title=&quot;D&#233;fenseur molthuni&quot;&gt;D&#233;fenseur molthuni&lt;/a&gt; (&lt;i&gt;AMH&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;fenseur-Du-Savoir-(Guerrier).html&quot; title=&quot;D&#233;fenseur du savoir&quot;&gt;D&#233;fenseur du savoir&lt;/a&gt; (RSE)&lt;/li&gt;
